backtracking(k, X[n]) BEGIN
 IF (esSolucion(k, X)) THEN BEGIN
 reportar(X);
 RETURN 1;
 END

 total <- 0;

 FOR cada candidato v EN candidatos(k, X) DO BEGIN
 IF (factible(k, v, X)) THEN BEGIN
 X[k] <- v;
 total <- total + backtracking(k + 1, X);
 X[k] <- NULL;
 END
 END

 RETURN total;
END

nReinas(n) BEGIN
 X[1..n] <- NULL;
 RETURN ubicarReina(1, n, X);
END

ubicarReina(fila, n, X[n]) BEGIN
 IF (fila = n + 1) THEN BEGIN
 reportar(X);
 RETURN 1;
 END

 total <- 0;

 FOR col <- 1 TO n DO BEGIN
 IF (esValida(fila, col, X)) THEN BEGIN
 X[fila] <- col;
 total <- total + ubicarReina(fila + 1, n, X);
 X[fila] <- NULL;
 END
 END

 RETURN total;
END

ubicarReinaRapido(fila, n, X[n], colUsada[n], diagA[2*n], diagB[2*n]) BEGIN
 IF (fila = n + 1) THEN BEGIN
 reportar(X);
 RETURN 1;
 END

 total <- 0;

 FOR col <- 1 TO n DO BEGIN
 dA <- fila - col + n;
 dB <- fila + col;

 IF (NOT colUsada[col] AND NOT diagA[dA] AND NOT diagB[dB]) THEN BEGIN
 X[fila] <- col;
 colUsada[col] <- T;
 diagA[dA] <- T;
 diagB[dB] <- T;

 total <- total + ubicarReinaRapido(fila + 1, n, X, colUsada, diagA, diagB);

 X[fila] <- NULL;
 colUsada[col] <- F;
 diagA[dA] <- F;
 diagB[dB] <- F;
 END
 END

 RETURN total;
END

